def longest_window(tickers, k):
    counts = {}
    best = 0
    left = 0
    for right in range(len(tickers)):
        t = tickers[right]
        counts[t] = counts.get(t, 0) + 1
        while len(counts) > k:
            u = tickers[left]
            counts[u] -= 1
            if counts[u] == 0:
                del counts[u]
            left += 1
        best = max(best, right - left + 1)
    return best

def range_sums(xs, queries):
    pre = [0]
    for x in xs:
        pre.append(pre[-1] + x)
    return [pre[r] - pre[l - 1] for l, r in queries]
